export const STARTUP_TIMEOUT_MS = 3_000;

export type BootstrapPhase = 'idle' | 'loading' | 'ready' | 'error';

export type BootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | 'startup-timeout'
  | 'startup-tooling-error'
  | 'invalid-startup-config';

export type BootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: BootstrapErrorReason;
      message: string;
      failedPhase: 'loading';
      recoverable: boolean;
    };

export interface BootstrapResult {
  state: BootstrapState;
  transitions: BootstrapState[];
}

export interface BootstrapOptions {
  env?: Record<string, string | undefined>;
  attempt?: number;
  timeoutMs?: number;
  now?: () => number;
  toolingCheck?: () => Promise<unknown>;
}

interface ValidUrlResult {
  ok: true;
  normalizedUrl: string;
}

interface InvalidUrlResult {
  ok: false;
  reason: Extract<BootstrapErrorReason, 'missing-api-base-url' | 'invalid-api-base-url'>;
  message: string;
}

const DEFAULT_IDLE_STATE: BootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_BOOTSTRAP_STATE = DEFAULT_IDLE_STATE;

export function createLoadingState(attempt: number, now: () => number): BootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
  };
}

export function validateApiBaseUrl(rawValue: string | undefined): ValidUrlResult | InvalidUrlResult {
  const value = rawValue?.trim();

  if (!value) {
    return {
      ok: false,
      reason: 'missing-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL is missing.',
    };
  }

  try {
    const parsed = new URL(value);

    if (parsed.protocol !== 'http:' && parsed.protocol !== 'https:') {
      return {
        ok: false,
        reason: 'invalid-api-base-url',
        message: 'EXPO_PUBLIC_API_BASE_URL must use http or https.',
      };
    }

    parsed.hash = '';

    return {
      ok: true,
      normalizedUrl: parsed.toString().replace(/\/$/, ''),
    };
  } catch {
    return {
      ok: false,
      reason: 'invalid-api-base-url',
      message: 'EXPO_PUBLIC_API_BASE_URL must be a valid absolute URL.',
    };
  }
}

function toBootstrapError(
  reason: BootstrapErrorReason,
  message: string,
  attempt: number,
  recoverable = true,
): BootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'loading',
    recoverable,
  };
}

function isValidStartupToolingResult(result: unknown): result is { status: 'ok' } {
  return !!result && typeof result === 'object' && (result as { status?: string }).status === 'ok';
}

async function defaultToolingCheck(): Promise<{ status: 'ok' }> {
  return { status: 'ok' };
}

async function runWithTimeout<T>(
  promise: Promise<T>,
  timeoutMs: number,
  message: string,
): Promise<T> {
  let timeoutHandle: ReturnType<typeof setTimeout> | undefined;

  const timeoutPromise = new Promise<T>((_, reject) => {
    timeoutHandle = setTimeout(() => {
      reject(new Error(message));
    }, timeoutMs);
  });

  try {
    return await Promise.race([promise, timeoutPromise]);
  } finally {
    if (timeoutHandle) {
      clearTimeout(timeoutHandle);
    }
  }
}

export async function runAppBootstrap(options: BootstrapOptions = {}): Promise<BootstrapResult> {
  const now = options.now ?? Date.now;
  const attempt = Math.max(1, options.attempt ?? 1);
  const timeoutMs = options.timeoutMs ?? STARTUP_TIMEOUT_MS;
  const toolingCheck = options.toolingCheck ?? defaultToolingCheck;
  const env = options.env ?? process.env;

  const loadingState = createLoadingState(attempt, now);
  const transitions: BootstrapState[] = [loadingState];

  try {
    const toolingResult = await runWithTimeout(
      toolingCheck(),
      timeoutMs,
      'Startup tooling check timed out.',
    );

    if (!isValidStartupToolingResult(toolingResult)) {
      const malformedConfigState = toBootstrapError(
        'invalid-startup-config',
        'Startup tooling returned an invalid configuration shape.',
        attempt,
        false,
      );
      transitions.push(malformedConfigState);
      return {
        state: malformedConfigState,
        transitions,
      };
    }
  } catch (error) {
    const reason: BootstrapErrorReason =
      error instanceof Error && error.message === 'Startup tooling check timed out.'
        ? 'startup-timeout'
        : 'startup-tooling-error';

    const toolingErrorState = toBootstrapError(
      reason,
      error instanceof Error ? error.message : 'Startup tooling check failed.',
      attempt,
      true,
    );
    transitions.push(toolingErrorState);

    return {
      state: toolingErrorState,
      transitions,
    };
  }

  const apiValidation = validateApiBaseUrl(env.EXPO_PUBLIC_API_BASE_URL);

  if (!apiValidation.ok) {
    const configErrorState = toBootstrapError(
      apiValidation.reason,
      apiValidation.message,
      attempt,
      false,
    );
    transitions.push(configErrorState);

    return {
      state: configErrorState,
      transitions,
    };
  }

  const readyState: BootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiValidation.normalizedUrl,
  };
  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

import { NavFloor } from '../../src/shared/types';
import { NormalizedNavGraph } from '../domain/navGraph';
import { normalizeNavGraph } from '../domain/navGraph';
import {
  type FloorPlanTarget,
  type MapApiClient,
  type MapApiErrorReason, MapApiResult, MapImageContract,
  createMapApiClient,
} from '../data/mapApiClient';
import { validateApiBaseUrl } from './appBootstrap';

export type MapBootstrapFetchPhase = 'map' | 'image';

export type MapBootstrapErrorReason =
  | 'missing-api-base-url'
  | 'invalid-api-base-url'
  | MapApiErrorReason
  | 'normalization-failure'
  | 'empty-graph';

export type MapBootstrapState =
  | {
      phase: 'idle';
      authRequired: false;
    }
  | {
      phase: 'loading';
      authRequired: false;
      attempt: number;
      startedAtMs: number;
      currentPhase: MapBootstrapFetchPhase;
      endpoint: string;
    }
  | {
      phase: 'ready';
      authRequired: false;
      attempt: number;
      apiBaseUrl: string;
      graph: NormalizedNavGraph;
      image: MapImageContract;
      imageTarget: FloorPlanTarget;
    }
  | {
      phase: 'error';
      authRequired: false;
      attempt: number;
      reason: MapBootstrapErrorReason;
      message: string;
      failedPhase: 'config' | MapBootstrapFetchPhase;
      endpoint: string | null;
      recoverable: boolean;
      details?: string[];
    };

export interface MapBootstrapResult {
  state: MapBootstrapState;
  transitions: MapBootstrapState[];
}

export interface MapBootstrapOptions {
  env?: Record<string, string | undefined>;
  attempt?: number;
  now?: () => number;
  clientFactory?: (baseUrl: string) => MapApiClient;
}

const IDLE_STATE: MapBootstrapState = {
  phase: 'idle',
  authRequired: false,
};

export const IDLE_MAP_BOOTSTRAP_STATE = IDLE_STATE;

function loadingState(
  currentPhase: MapBootstrapFetchPhase,
  endpoint: string,
  attempt: number,
  now: () => number,
): MapBootstrapState {
  return {
    phase: 'loading',
    authRequired: false,
    attempt,
    startedAtMs: now(),
    currentPhase,
    endpoint,
  };
}

function toConfigError(reason: 'missing-api-base-url' | 'invalid-api-base-url', message: string, attempt: number): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason,
    message,
    failedPhase: 'config',
    endpoint: null,
    recoverable: false,
  };
}

function toMapApiError(
  failedPhase: MapBootstrapFetchPhase,
  attempt: number,
  result: Extract<MapApiResult<unknown>, { ok: false }>,
): MapBootstrapState {
  const isRecoverable = result.error.reason !== 'contract-validation-error';

  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: result.error.reason,
    message: result.error.message,
    failedPhase,
    endpoint: result.error.endpoint,
    recoverable: isRecoverable,
    ...(result.error.details ? { details: result.error.details } : {}),
  };
}

function toNormalizationError(
  attempt: number,
  endpoint: string,
  message: string,
  details?: string[],
): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: 'normalization-failure',
    message,
    failedPhase: 'map',
    endpoint,
    recoverable: false,
    ...(details && details.length > 0 ? { details } : {}),
  };
}

function toEmptyGraphError(attempt: number, endpoint: string): MapBootstrapState {
  return {
    phase: 'error',
    authRequired: false,
    attempt,
    reason: 'empty-graph',
    message: 'Map payload contained no floors to bootstrap.',
    failedPhase: 'map',
    endpoint,
    recoverable: false,
  };
}

function pickInitialFloor(graph: NormalizedNavGraph): FloorPlanTarget | null {
  for (const building of graph.graph.buildings) {
    const floor = pickFirstFloor(building.floors);
    if (!floor) {
      continue;
    }

    return {
      buildingId: building.id,
      floorNumber: floor.floorNumber,
    };
  }

  return null;
}

function pickFirstFloor(floors: NavFloor[]): NavFloor | null {
  if (floors.length === 0) {
    return null;
  }

  const sortedFloors = [...floors].sort((a, b) => a.floorNumber - b.floorNumber);
  return sortedFloors[0] ?? null;
}

export async function runMapBootstrap(options: MapBootstrapOptions = {}): Promise<MapBootstrapResult> {
  const attempt = Math.max(1, options.attempt ?? 1);
  const env = options.env ?? process.env;
  const now = options.now ?? Date.now;

  const apiBase = validateApiBaseUrl(env.EXPO_PUBLIC_API_BASE_URL);
  if (!apiBase.ok) {
    const configError = toConfigError(apiBase.reason, apiBase.message, attempt);
    return {
      state: configError,
      transitions: [configError],
    };
  }

  const client = options.clientFactory
    ? options.clientFactory(apiBase.normalizedUrl)
    : createMapApiClient({ baseUrl: apiBase.normalizedUrl });

  const transitions: MapBootstrapState[] = [];

  const mapLoading = loadingState('map', client.resolveMapUrl(), attempt, now);
  transitions.push(mapLoading);

  const mapResult = await client.fetchMapGraph();
  if (!mapResult.ok) {
    const mapError = toMapApiError('map', attempt, mapResult);
    transitions.push(mapError);
    return {
      state: mapError,
      transitions,
    };
  }

  const normalized = normalizeNavGraph(mapResult.data);
  if (!normalized.ok) {
    const normalizationError = toNormalizationError(
      attempt,
      mapResult.endpoint,
      normalized.error.message,
      [normalized.error.code],
    );
    transitions.push(normalizationError);
    return {
      state: normalizationError,
      transitions,
    };
  }

  const imageTarget = pickInitialFloor(normalized.data);
  if (!imageTarget) {
    const emptyGraphError = toEmptyGraphError(attempt, mapResult.endpoint);
    transitions.push(emptyGraphError);
    return {
      state: emptyGraphError,
      transitions,
    };
  }

  const imageLoading = loadingState(
    'image',
    client.resolveFloorPlanImageUrl(imageTarget),
    attempt,
    now,
  );
  transitions.push(imageLoading);

  const imageResult = await client.fetchFloorPlanImageContract(imageTarget);
  if (!imageResult.ok) {
    const imageError = toMapApiError('image', attempt, imageResult);
    transitions.push(imageError);
    return {
      state: imageError,
      transitions,
    };
  }

  const readyState: MapBootstrapState = {
    phase: 'ready',
    authRequired: false,
    attempt,
    apiBaseUrl: apiBase.normalizedUrl,
    graph: normalized.data,
    image: imageResult.data,
    imageTarget,
  };

  transitions.push(readyState);

  return {
    state: readyState,
    transitions,
  };
}

